// PRSyncJobCreateBulk is the builder for creating many PRSyncJob entities in bulk.
type PRSyncJobCreateBulk struct {
	config
	err      error
	builders []*PRSyncJobCreate
}

// Save creates the PRSyncJob entities in the database.
func (psjcb *PRSyncJobCreateBulk) Save(ctx context.Context) ([]*PRSyncJob, error) {
	if psjcb.err != nil {
		return nil, psjcb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(psjcb.builders))
	nodes := make([]*PRSyncJob, len(psjcb.builders))
	mutators := make([]Mutator, len(psjcb.builders))
	for i := range psjcb.builders {
		func(i int, root context.Context) {
			builder := psjcb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*PRSyncJobMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, psjcb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, psjcb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				if specs[i].ID.Value != nil {
					id := specs[i].ID.Value.(int64)
					nodes[i].ID = int(id)
				}
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, psjcb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

